"""Canned LLM responses for the sample conversations - TEST USE ONLY.

These stand in for the OpenAI API so the suite runs without paid calls. They are not used
at runtime. Several deliberately disagree with the business rules (e.g. S07 proposes MEDIUM
for a security incident, S10 proposes URGENT because the customer is angry) so the tests can
prove the deterministic rules win.
"""


def I(summary, evidence, *, ref=None, impact=None, req=None, missing=(), affected=None, amount=None,
      deadline=None, deadline_hours=None, cls, prio, res):
    return {
        "extraction": {
            "summary": summary, "evidence": list(evidence), "customer_ref": ref, "customer_impact": impact,
            "requested_action": req, "missing_information": list(missing), "affected_users": affected,
            "amount": amount, "deadline_text": deadline, "deadline_hours": deadline_hours,
        },
        "classification": {"issue_type": cls[0], "category": cls[1], "subcategory": cls[2],
                           "confidence": cls[3], "rationale": "mock", "needs_review": cls[1] == "other_needs_review"},
        "prioritization": {"priority": prio[0], "factors": prio[1], "confidence": prio[2],
                           "needs_review": False},
        "resolution": {"ticket_title": res[0], "next_action": res[1], "requires_human_approval": res[2],
                       "approval_reason": res[3] if len(res) > 3 else None},
    }


